    const condition=assets.length?Math.round(assets.reduce((n,a)=>n+(Number(a.condition)||100),0)/assets.length):(assetCount?100:0),contracts=(ctx.state.advanced?.labor?.employmentContracts||[]).filter(c=>String(c.ownerCompanyId||c.company||'')===type&&c.status==='ساري'),assetCrewContracts=contracts.filter(c=>c.automaticAssetStaffing),managedContracts=contracts.filter(c=>!c.automaticAssetStaffing),assetCrew=assetCrewContracts.reduce((n,c)=>n+(Number(c.count)||1),0),managedPeople=managedContracts.reduce((n,c)=>n+(Number(c.count)||1),0);
