    if(active==='finance'&&type==='power'){const e=globalThis.GH_ENERGY_CORE?.economics?.(ctx.state)||{};body+=`<article class="list-item"><h3>تفصيل إيرادات الطاقة</h3>${metrics([['PPA',ctx.fmtMoney(e.ppaRevenue||0)],['السوق الفوري',ctx.fmtMoney(e.spotRevenue||0)],['التخزين',ctx.fmtMoney(e.storageRevenue||0)],['السعة والموازنة',ctx.fmtMoney(Number(e.capacityRevenue||0)+Number(e.balancingRevenue||0))]])}<div class="action-row"><button class="primary-btn" data-open="energy" data-arg="revenue">فتح مركز إيرادات الطاقة</button></div></article>`;}
