    if(tab==='overview')content=`<article class="list-item"><div class="list-item-head"><div><h3>شركة الطاقة · اليوم التشغيلي</h3><p>الإيراد المعروض هنا هو نفس الإيراد الذي يدخل الإقفال المالي للشركة، وليس مؤشرًا منفصلًا.</p></div><span class="tag ${summary.net>=0?'positive':'negative'}">${summary.net>=0?'ربحية موجبة':'تحت الضغط'}</span></div>${metrics([['الإيراد',ctx.fmtMoney(summary.powerRevenue)],['المصروف',ctx.fmtMoney(summary.powerExpense)],['خدمة الدين',ctx.fmtMoney(summary.debtService)],['الصافي',ctx.fmtMoney(summary.net),summary.net>=0?'positive':'negative']])}${metrics([['محطات عاملة',operating.length],['قيد التطوير',projects.length],['إنتاج',`${ctx.fmtNumber(summary.generation)} MWh`],['عقود PPA',contracts.length]])}<div class="action-row"><button class="primary-btn" data-energy-tab="revenue">تفصيل الإيرادات</button>${action('energy-world-directory','فتح مشروع/موقع جديد')}<button class="secondary-btn" data-open="companyManage" data-arg="power:management">إدارة الشركة</button></div></article>${operating.slice(0,20).map(site=>`<article class="list-item"><div class="list-item-head"><div><h3>${ctx.esc(site.name)}</h3><p>${ctx.esc(site.city)} · ${ctx.esc(kindName(site.kind))}</p></div><span class="tag positive">${ctx.esc(site.status)}</span></div>${metrics([['إيراد اليوم',ctx.fmtMoney(site.dailyRevenue||0)],['مصروف اليوم',ctx.fmtMoney(site.dailyExpense||0)],['تدفق حر',ctx.fmtMoney(site.freeCashFlow||0),Number(site.freeCashFlow)>=0?'positive':'negative'],['الإتاحة',`${(Number(site.availability||0)*100).toFixed(1)}%`]])}</article>`).join('')||'<div class="empty">لا يوجد مشروع في التشغيل التجاري بعد.</div>'}`;
    if(tab==='revenue')content=`<article class="list-item revenue-center"><div class="list-item-head"><div><h3>مركز إيرادات الطاقة</h3><p>كل فئة محسوبة مرة واحدة ضمن إجمالي إيراد الطاقة في الإقفال المالي.</p></div><span class="tag positive">${ctx.fmtMoney(summary.powerRevenue)}</span></div>${metrics([['عقود PPA',ctx.fmtMoney(summary.ppaRevenue)],['السوق الفوري',ctx.fmtMoney(summary.spotRevenue)],['التخزين/المراجحة',ctx.fmtMoney(summary.storageRevenue)],['شهادات متجددة',ctx.fmtMoney(summary.recRevenue)]])}${metrics([['مدفوعات السعة',ctx.fmtMoney(summary.capacityRevenue||0)],['الموازنة والاحتياطي',ctx.fmtMoney(summary.balancingRevenue||0)],['إجمالي الإيراد',ctx.fmtMoney(summary.powerRevenue),'positive'],['EBITDA',ctx.fmtMoney(summary.ebitda),summary.ebitda>=0?'positive':'negative']])}</article>${operating.map(site=>`<article class="list-item"><h3>${ctx.esc(site.name)}</h3>${metrics([['PPA',ctx.fmtMoney(site.ppaRevenue||0)],['سوق',ctx.fmtMoney(site.spotRevenue||0)],['تخزين',ctx.fmtMoney(site.storageRevenue||0)],['سعة/موازنة',ctx.fmtMoney(Number(site.capacityRevenue||0)+Number(site.balancingRevenue||0))]])}</article>`).join('')||'<div class="empty">لا توجد إيرادات قبل التشغيل التجاري.</div>'}`;
