    let operations;try{operations=JSON.parse(pack.operationsJSON);}catch{throw new Error('operationsJSON غير صالح.');}if(!Array.isArray(operations))throw new Error('operationsJSON يجب أن يمثل مصفوفة عمليات.');const allowedOps=new Set(['content-config','balance-config','economy-config','add-events','visual-manifest']);for(const op of operations){if(!op||!allowedOps.has(op.type))throw new Error(`عملية تحديث غير مدعومة: ${String(op?.type||'فارغة')}`);}
